CREATE OR REPLACE FUNCTION public.f90_i18n_enqueue(p_source text,p_context text,p_public boolean) RETURNS void LANGUAGE plpgsql SET search_path='' AS $$ DECLARE s text:=trim(regexp_replace(coalesce(p_source,''),'\s+',' ','g')); BEGIN IF s='' OR length(s)>12000 OR s!~'[ء-ي]' THEN RETURN;END IF; INSERT INTO public.f90_i18n_text(source_text,en,fr,pt,is_public,provider) VALUES(s,s,s,s,p_public,'pending') ON CONFLICT(source_text) DO UPDATE SET is_public=f90_i18n_text.is_public OR EXCLUDED.is_public; IF EXISTS(SELECT 1 FROM public.f90_i18n_text WHERE source_text=s AND (provider='pending' OR en='' OR fr='' OR pt='')) THEN INSERT INTO public.f90_i18n_jobs(source_text,source_hash,contexts) VALUES(s,md5(s),jsonb_build_object(p_context,true)) ON CONFLICT(source_text) DO UPDATE SET contexts=f90_i18n_jobs.contexts||EXCLUDED.contexts,status=CASE WHEN f90_i18n_jobs.status='complete' THEN 'pending' ELSE f90_i18n_jobs.status END,updated_at=now();END IF;END $$;
